#include <stdio.h>

/* 带参宏求余数：每个参数都要加括号，防止实参是表达式时优先级出错 */
#define REM(a, b) ((a) % (b))

int main(void)
{
    int a, b;

    if (scanf("%d %d", &a, &b) != 2)
        return 1;
    printf("remainder=%d\n", REM(a, b));

    return 0;
}

#include <stdio.h>

/* 交换宏必须用 do{}while(0) 包起来，临时变量才不会漏到外层作用域 */
#define SWAP(x, y) do { int swap_tmp_ = (x); (x) = (y); (y) = swap_tmp_; } while (0)

int main(void)
{
    int a[100], b[100];
    int n, i;

    if (scanf("%d", &n) != 1)
        return 1;
    if (n < 1 || n > 100)
        return 1;

    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &b[i]) != 1)
            return 1;

    for (i = 0; i < n; i++)
        SWAP(a[i], b[i]);

    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");
    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", b[i]);
    }
    printf("\n");

    return 0;
}

#include <stdio.h>

/* 判断字符是否为字母：不用 ctype.h 的 isalpha，直接比 ASCII 区间 */
#define IS_ALPHA(c) (((c) >= 'a' && (c) <= 'z') || ((c) >= 'A' && (c) <= 'Z'))

int main(void)
{
    char ch;

    if (scanf("%c", &ch) != 1)
        return 1;
    if (IS_ALPHA(ch))
        printf("yes\n");
    else
        printf("no\n");

    return 0;
}

#include <stdio.h>

/* 判断整数 n 是否能被 x 整除 */
#define DIVISIBLE(n, x) ((n) % (x) == 0)

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1)
        return 1;
    if (DIVISIBLE(n, 3) && DIVISIBLE(n, 7))
        printf("yes\n");
    else
        printf("no\n");

    return 0;
}

#include <stdio.h>
#include <math.h>

/* 两个带参宏分别实现 s = (a+b+c)/2 与海伦公式 */
#define S(a, b, c) (((a) + (b) + (c)) / 2.0)
#define AREA(s, a, b, c) (sqrt((s) * ((s) - (a)) * ((s) - (b)) * ((s) - (c))))

int main(void)
{
    double a, b, c, s, area;

    if (scanf("%lf %lf %lf", &a, &b, &c) != 3)
        return 1;

    s = S(a, b, c);
    area = AREA(s, a, b, c);
    printf("area=%.2f\n", area);

    return 0;
}
